from solution import set_spa_filter
import pytest

class MockBlock:

    def __init__(self, idx):
        self.idx = idx
        self.attn = MockAttn()

class MockAttn:

    class Processor:

        def __init__(self):
            self.spa_allowed = None

        @property
        def spa_allowed(self):
            raise AttributeError('Cannot read')

        @spa_allowed.setter
        def spa_allowed(self, value):
            self._spa_allowed = value

    def __init__(self):
        self.processor = self.Processor()

class MockTransformer:

    def __init__(self, num_double=2, num_single=2):
        self.transformer_blocks = [MockBlock(i) for i in range(num_double)]
        self.single_transformer_blocks = [MockBlock(i) for i in range(num_single)]

