    transformer = MockTransformer()
    set_spa_filter(transformer)
    for block in transformer.transformer_blocks:
        assert block.attn.processor._spa_allowed is True
    for block in transformer.single_transformer_blocks:
        assert block.attn.processor._spa_allowed is True

